Write a Java program to accept a student's name and display a personalized greeting based on the time of day. Additionally, include a validation check to ensure that the user inputs a valid name (not an empty string or containing numbers). Implement the validation check using regular expressions.

### Response:
import java.util.Scanner;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class GreetingProgram {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Accept the student's name
        String name = "";
        while (name.isEmpty() || containsNumbers(name)) {
            System.out.print("Enter your name: ");
            name = scanner.nextLine();
            if (name.isEmpty()) {
                System.out.println("Name cannot be empty. Please try again.");
            } else if (containsNumbers(name)) {
                System.out.println("Name cannot contain numbers. Please try again.");
            }
        }

        // Display personalized greeting based on time of day
        String greeting = getGreeting();
        System.out.println(greeting + ", " + name + "!");
    }

    private static boolean containsNumbers(String input) {
        Pattern pattern = Pattern.compile(".*\\d.*");
        Matcher matcher = pattern.matcher(input);
        return matcher.matches();
    }

    private static String getGreeting() {
        int hour = java.time.LocalTime.now().getHour();
        if (hour >= 5 && hour < 12) {
            return "Good morning";
        } else if (hour >= 12 && hour < 17) {
            return "Good afternoon";
        } else {
            return "Good evening";
        }
    }
}

