        }}
      />
      <input
        type="password"
        placeholder="Confirm Password"
        value={confirmPassword}
        onChange={(e) => {
          setConfirmPassword(e.target.value);
          validateForm();
        }}
      />
      <input
        type="text"
        placeholder="Address"
        value={address}
        onChange={(e) => {
          setAddress(e.target.value);
          validateForm();
        }}
      />
      <input
        type="text"
        placeholder="City"
        value={city}
        onChange={(e) => {
          setCity(e.target.value);
          validateForm();
        }}
      />
      <input
        type="text"
        placeholder="State"
        value={state}
        onChange={(e) => {
          setState(e.target.value);
