### Instruction:
Implement a React component that represents a game of Simon Says. The game should have four colored buttons (red, blue, green, yellow) that light up in a random pattern. The player should have to repeat the pattern by clicking the buttons in the correct order. If the player clicks the wrong button, the game should end and display a message saying "Game over!". The game should also have a timer that counts down from 30 seconds, and if the player does not complete the pattern within the countdown, it should display a message saying "Time's up!".

### Response:
Sure! Here's an example implementation of a Simon Says game component in React:

```jsx
import React, { useState, useEffect } from 'react';

const SimonSaysGame = () => {
  const colors = ['red', 'blue', 'green', 'yellow'];
  const [pattern, setPattern] = useState([]);
  const [playerPattern, setPlayerPattern] = useState([]);
  const [gameOver, setGameOver] = useState(false);
  const [timesUp, setTimesUp] = useState(false);
  const [timeLeft, setTimeLeft] = useState(30);

  // Function to start the game
  const startGame = () => {
    setPattern([]);
    setPlayerPattern([]);
    setGameOver(false);
    setTimesUp(false);
    setTimeLeft(30);
    generatePattern();
  };

  // Function to generate a random pattern
  const generatePattern = () => {
    const randomColor = colors[Math.floor(Math.random() * colors.length)];
    setPattern((prevPattern) => [...prevPattern, randomColor]);
  };

  // Function to handle player clicks
  const handleClick = (color) => {
    if (gameOver || timesUp) return;

    setPlayerPattern((prevPattern) => [...prevPattern, color]);

    if (!checkPattern()) {
      setGameOver(true);
    }
  };

  // Function to check if player pattern matches the game pattern
  const checkPattern = () => {
    for (let i = 0; i < playerPattern.length; i++) {
      if (playerPattern[i] !== pattern[i]) {
        return false;
      }
    }
    if (playerPattern.length === pattern.length) {
      setPlayerPattern([]);
      generatePattern();
    }
    return true;
  };

  // Function to handle timer countdown
  useEffect(() => {
    if (timeLeft === 0) {
      setTimesUp(true);
    }

    const timer = setInterval(() => {
      setTimeLeft((prevTime) => prevTime - 1);
    }, 1000);

    return () => clearInterval(timer);
  }, [timeLeft]);

  // Render the game
  return (
    <div>
      <h1>Simon Says</h1>
      <div className="buttons">
        {colors.map((color) => (
          <button
            key={color}
            className={`button ${color}`}
            onClick={() => handleClick(color)}
            disabled={gameOver || timesUp}
          >
            {color}
          </button>
        ))}
      </div>
      <div className="messages">
        {gameOver && <p>Game over!</p>}
        {timesUp && <p>Time's up!</p>}
      </div>
      <div className="timer">Time left: {timeLeft}</div>
      <button onClick={startGame}>Start Game</button>
    </div>
  );
};

export default SimonSaysGame;
```

