Create a ReactJS component to display a modal window with a form. The form should have the following fields:
- Name (required, maximum length of 50 characters)
- Email (required, valid email address)
- Password (required, minimum length of 8 characters, at least one uppercase letter, one lowercase letter, and one special character)
- Confirm Password (required, must match the Password field)

The modal window should also have the following features:
- The modal should close when the user clicks outside of the form.
- Display an error message for each invalid field when the user tries to submit the form.
- Upon successful form submission, display a success message and clear the form fields.

You should also write unit tests to verify the functionality of the component.

### Response:
import React, { useState } from "react";

const ModalForm = () => {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [errors, setErrors] = useState([]);
  const [successMessage, setSuccessMessage] = useState("");

  const validateForm = () => {
    let formErrors = [];
    if (!name) {
      formErrors.push("Name is required");
    } else if (name.length > 50) {
      formErrors.push("Name cannot exceed 50 characters");
    }
    if (!email) {
      formErrors.push("Email is required");
    } else if (!isValidEmail(email)) {
      formErrors.push("Invalid email address");
    }
    if (!password) {
      formErrors.push("Password is required");
    } else if (!isValidPassword(password)) {
      formErrors.push(
        "Password must be at least 8 characters long, contain at least one uppercase letter, one lowercase letter, and one special character"
      );
    }
    if (!confirmPassword) {
      formErrors.push("Confirm Password is required");
    } else if (password !== confirmPassword) {
      formErrors.push("Passwords do not match");
    }
    setErrors(formErrors);
    return formErrors.length === 0;
  };

  const isValidEmail = (email) => {
    const emailRegex = /^[\w-]+(\.[\w-]+)*@([\w-]+\.)+[a-zA-Z]{2,7}$/;
    return emailRegex.test(email);
  };

  const isValidPassword = (password) => {
    const passwordRegex = /^(?=.*\d)(?=.*[a-z])(?=.*[A-Z])(?=.*[!@#$%^&*]).{8,}$/;
    return passwordRegex.test(password);
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (validateForm()) {
      // Perform form submission logic here
      setSuccessMessage("Form submitted successfully");
      setName("");
      setEmail("");
      setPassword("");
      setConfirmPassword("");
    }
  };

  return (
    <div className="modal">
      <form className="modal-form" onSubmit={handleSubmit}>
        <div className="form-group">
          <label htmlFor="name">Name:</label>
          <input
            type="text"
            id="name"
            value={name}
            onChange={(e) => setName(e.target.value)}
          />
        </div>
        <div className="form-group">
          <label htmlFor="email">Email:</label>
          <input
            type="email"
            id="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
          />
        </div>
        <div className="form-group">
          <label htmlFor="password">Password:</label>
          <input
            type="password"
            id="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
          />
        </div>
        <div className="form-group">
          <label htmlFor="confirmPassword">Confirm Password:</label>
          <input
            type="password"
            id="confirmPassword"
            value={confirmPassword}
            onChange={(e) => setConfirmPassword(e.target.value)}
          />
        </div>
        <button type="submit">Submit</button>
        {errors.length > 0 && (
          <div className="error-messages">
            {errors.map((error, index) => (
              <p key={index}>{error}</p>
            ))}
          </div>
        )}
        {successMessage && <p className="success-message">{successMessage}</p>}
      </form>
    </div>
  );
};

export default ModalForm;

