        "_attributes": {
          "class": "heading"
        },
        "_value": "Hello <span style=\"color: red;\">World!</span>"
      },
      "p": "This is a paragraph with <a href=\"https://example.com\">a link</a> and an image: <img src=\"image.jpg\" alt=\"Image\">"
    }
  }
