     { label: '18-24', minAge: 18, maxAge: 24 },
     { label: '25-34', minAge: 25, maxAge: 34 },
     { label: '35-44', minAge: 35, maxAge: 44 },
     { label: '45+', minAge: 45, maxAge: Infinity },
   ];

   const genders = ['male', 'female'];

   const filterData = (nameFilter, ageRangeFilter, genderFilter) => {
     let filteredData = data;

     if (nameFilter) {
       filteredData = filteredData.filter((person) => person.name.toLowerCase().includes(nameFilter.toLowerCase()));
     }

     if (ageRangeFilter) {
